def load_phase_catalog():
    import yaml
    return yaml.safe_load((HERE / 'config/phase_catalog.yaml').read_text(encoding='utf-8'))['phases']

def assignment(phase):
    """Reuse the catalog's current phase instruction; no separate prompt registry."""
    item = next((p for p in load_phase_catalog() if p['id'] == phase), None)
    if item is None:
        return {}
    return {'phase': phase, 'instruction': item['gate'],
            'evidence_help': str(HERE / 'references/execution.md') + '#receipts',
            'then': 'Save actual evidence and record this phase before starting the next. Ask and wait if a material user decision is missing.'}

def run_tool(script, *args):
    result = subprocess.run([sys.executable, '-X', 'utf8', str(HERE / 'scripts' / script), *map(str, args)],
                            capture_output=True, text=True, encoding='utf-8', timeout=60)
    try:
        payload = json.loads(result.stdout)
    except ValueError:
        payload = {'status': 'blocked', 'errors': [result.stderr.strip() or result.stdout.strip() or 'No tool output']}
    if result.returncode and payload.get('status') in ('approved', 'ok'):
        payload = {'status': 'blocked', 'errors': ['Tool failed despite a passing payload']}
    return payload

def run_preflight(target_path, ignore_paths=None):
    result = subprocess.run([sys.executable, '-X', 'utf8', str(HERE / 'scripts/preflight_worktree.py'),
                             str(target_path), *(ignore_paths or [])],
                            capture_output=True, text=True, encoding='utf-8', timeout=30)
    return {'status': {0: 'approved', 2: 'flagged'}.get(result.returncode, 'blocked'),
            'target': str(target_path), 'exit_code': result.returncode,
            'stdout': result.stdout, 'stderr': result.stderr}

def run_receipt_validator(receipt_path, manifest_path=None):
    args = [receipt_path] + (['--manifest', manifest_path] if manifest_path else [])
    return run_tool('validate_receipt.py', *args)

def load_manifest(run):
    import yaml
    return yaml.safe_load((run / 'manifest.yaml').read_text(encoding='utf-8'))

def owned_run(value):
    run = private_path(value)
    state = json.loads((run / 'run.json').read_text(encoding='utf-8'))
    root = personal_root()
    if str(root) != state['personal_root'] or private_path(run, root / 'arc_runs') != run:
        raise ValueError('Run does not belong to the configured personal folder')
    if run.parent != (root / 'arc_runs').resolve() or run.name != state['run_id']:
        raise ValueError('Run location does not match its recorded identity')
    # Check nested write targets even for resumed runs.
    for name in ('receipts', 'report.md', 'ledger.jsonl', 'check_result.json'):
        private_path(run / name, run)
    return run

def append_event(run, event, **fields):
    path = private_path(run / 'ledger.jsonl', run)
    payload = {'event': event, 'run_id': run.name, 'ts': now(), **fields}
    with path.open('a', encoding='utf-8') as handle:
        handle.write(json.dumps(payload, ensure_ascii=False) + '\n')

def events(run):
    path = run / 'ledger.jsonl'
    return [json.loads(line) for line in path.read_text(encoding='utf-8').splitlines() if line.strip()] if path.exists() else []

def save_report(run, result):
    state = json.loads((run / 'run.json').read_text(encoding='utf-8'))
    try:
        manifest = load_manifest(run) if (run / 'manifest.yaml').exists() else {}
    except Exception:
        manifest = {}
    completed = {e.get('phase') for e in events(run) if e['event'] == 'phase_done' and e.get('ok')}
    lines = ['# Delivery Workflow report', '', f"Status: **{result['status']}**", '',
             f"Run: `{run.name}`", f"Project: `{state['project_root']}`", '']
    if manifest.get('task_ref'):
        lines += [f"[Task and scope](<{manifest['task_ref']}>)", '']
    if 'postmortem' in completed:
        try:
            receipt = json.loads((run / 'receipts/postmortem.json').read_text(encoding='utf-8'))
            source = Path(receipt['evidence']['postmortem_ref'])
            outcome = source.read_text(encoding='utf-8').strip().splitlines()
            if outcome and outcome[0].startswith('# '):
                outcome = outcome[1:]
            lines += ['## Recorded outcome and remaining work', '', '\n'.join(outcome).strip(), '',
                      f'[Full postmortem](<{source}>)', '']
        except (OSError, ValueError, KeyError):
            lines += ['Recorded postmortem is unavailable; inspect the check errors below.', '']
    lines += ['## Phase evidence', '', '| Phase | State | Evidence |', '| --- | --- | --- |']
    for phase in manifest.get('phases', []):
        name = phase['phase']
        if phase['decision'] == 'excluded':
            lines.append(f"| {name} | excluded: {phase['reason_code']} | {phase.get('evidence_ref', '')} |")
        else:
            done = name in completed
            lines.append(f"| {name} | {'recorded' if done else 'pending'} | {'[receipt](receipts/' + name + '.json)' if done else ''} |")
    lines += ['', '## Latest check', '', '```json', json.dumps(result, ensure_ascii=False, indent=2), '```', '',
              '## Scope and limits', '',
              'The coordinator checks evidence structure, file references and recorded order. It does not prove',
              'semantic correctness, a model identity, or that a supplied log describes an actual execution.',
              'Read the task, phase evidence and postmortem for changes, observed behavior and remaining gaps.',
              'Git changes and publication are separate from evidence completion. This coordinator never commits or pushes.', '']
    write(run / 'report.md', '\n'.join(lines), run)
    response = {**result, 'run_dir': str(run), 'report': str(run / 'report.md')}
    if result.get('next') in {p.get('phase') for p in manifest.get('phases', [])}:
        response['assignment'] = assignment(result['next'])
    return response

def integrity_errors(run, manifest):
    errors = []
    audit = json.loads((run / 'audit_result.json').read_text(encoding='utf-8'))
    state = json.loads((run / 'run.json').read_text(encoding='utf-8'))
    if audit.get('status') != 'approved' or audit.get('run_id') != manifest.get('run_id') or manifest.get('run_id') != run.name:
        errors.append('A matching approved audit is required')
    if manifest.get('project_root') != state.get('project_root'):
        errors.append('Project identity changed after initialization')
    for key, path in [('manifest_sha256', run / 'manifest.yaml'), ('task_sha256', Path(manifest['task_ref'])),
                      ('lessons_sha256', run / 'lessons_snapshot.yaml'), ('preflight_sha256', run / 'preflight_result.json')]:
        if not path.is_file() or digest(path) != audit.get(key):
            errors.append(f'{key}: evidence changed or is missing; create a revised audit')
    return errors

def cmd_record(run_value, receipt_value):
    run = owned_run(run_value)
    with locked(run):
        manifest = load_manifest(run)
        errors = integrity_errors(run, manifest)
        receipt_path = Path(receipt_value).expanduser().resolve()
        receipt = json.loads(receipt_path.read_text(encoding='utf-8'))
        if receipt.get('phase') == 'understand':
            observed = json.loads((run / 'preflight_result.json').read_text(encoding='utf-8'))
            claimed = receipt.get('evidence', {}).get('preflight', {})
            expected = 'override' if observed['status'] == 'flagged' else 'clean'
            if claimed.get('status') != expected or Path(claimed.get('evidence_ref', '')).resolve() != (run / 'preflight_result.json').resolve():
                errors.append('Understand receipt must cite this run\'s actual preflight and status')
        included = [p['phase'] for p in manifest['phases'] if p['decision'] == 'included']
        done = [e['phase'] for e in events(run) if e['event'] == 'phase_done' and e.get('ok')]
        if any(e['event'] == 'stopped' for e in events(run)):
            errors.append('This run was stopped; revise the approach in a new run')
        for prior in done:
            prior_path = private_path(run / 'receipts' / f'{prior}.json', run)
            recorded = next(e for e in events(run) if e['event'] == 'phase_done' and e['phase'] == prior)
            if not prior_path.is_file() or digest(prior_path) != recorded.get('receipt_sha256'):
                errors.append(f'{prior}: earlier evidence changed or is missing')
            elif run_receipt_validator(prior_path, run / 'manifest.yaml').get('status') != 'approved':
                errors.append(f'{prior}: earlier evidence no longer validates')
        phase = receipt.get('phase')
        if done != included[:len(done)] or len(done) == len(included) or phase != included[len(done)]:
            errors.append('Receipt must be for the next included phase; recorded phases cannot be overwritten')
        result = run_receipt_validator(receipt_path, run / 'manifest.yaml')
        errors += result.get('errors', [])
        if result.get('status') != 'approved' and not result.get('errors'):
            errors.append('Receipt validator did not approve')
        if errors:
            return save_report(run, {'status': 'blocked', 'errors': errors})
        destination = private_path(run / 'receipts' / f'{phase}.json', run)
        if destination.exists():
            raise ValueError('Receipt already exists; inspect interrupted writes before recovery')
        # References must be absolute, or resolve from the final receipt location too.
        write_json(destination, receipt, run)
        bound = run_receipt_validator(destination, run / 'manifest.yaml')
        if bound.get('status') != 'approved':
            destination.unlink()
            return save_report(run, {'status': 'blocked', 'errors': bound.get('errors', ['Evidence paths do not resolve at the saved location'])})
        append_event(run, 'phase_done', phase=phase, ok=True, receipt_sha256=digest(destination))
        result = {'status': 'incomplete', 'recorded': phase, 'warnings': bound.get('warnings', []),
                  'next': included[len(done) + 1] if len(done) + 1 < len(included) else 'check'}
        if phase == 'spike' and receipt['evidence'].get('verdict') == 'INVALIDATED':
            append_event(run, 'stopped', reason='Approach invalidated')
            result.update(status='stopped', next='Revise the approach in a new run')
        return save_report(run, result)

def _task_git_root(manifest, run_dir):
    task = Path(manifest['task_ref'])
    if not task.is_file():
        return None, 'task_not_found'
    project = Path(manifest.get('project_root', task.parent))
    if not project.is_dir():
        return None, 'project_not_found'
    result = subprocess.run(['git', '-C', str(project), 'rev-parse', '--show-toplevel'], capture_output=True, text=True, timeout=15)
    if result.returncode:
        if any((p / '.git').exists() for p in (project, *project.parents)):
            return None, 'git_error'
        return None, 'no_git'
    return Path(result.stdout.strip()).resolve(), None

def git_state(manifest, run):
    root, reason = _task_git_root(manifest, run)
    if reason and reason != 'no_git':
        return {'status': 'error', 'error': 'GIT GATE: ' + reason}
    if root is None:
        return {'status': 'no-git', 'publication': 'not-applicable'}
    result = subprocess.run(['git', '-C', str(root), 'status', '--porcelain', '--untracked-files=all'], capture_output=True, text=True, timeout=15)
    if result.returncode:
        return {'status': 'error', 'error': 'Git status could not be read'}
    head = subprocess.run(['git', '-C', str(root), 'rev-parse', 'HEAD'], capture_output=True, text=True, timeout=15)
    return {'status': 'working-changes' if result.stdout.strip() else 'clean', 'root': str(root),
            'head': head.stdout.strip() if head.returncode == 0 else None,
            'changes': result.stdout.splitlines(), 'publication': 'not-checked'}

def cmd_check(run_value, dry_run=False):
    run = owned_run(run_value)
    with locked(run):
        manifest = load_manifest(run)
        errors = integrity_errors(run, manifest)
        warnings = []
        ledger = events(run)
        if any(e['event'] == 'stopped' for e in ledger):
            errors.append('Approach was invalidated; this run is stopped')
        included = [p['phase'] for p in manifest['phases'] if p['decision'] == 'included']
        for phase in included:
            receipt_path = private_path(run / 'receipts' / f'{phase}.json', run)
            if not receipt_path.is_file():
                errors.append(f'{phase}: missing receipt')
                continue
            receipt = json.loads(receipt_path.read_text(encoding='utf-8'))
            if receipt.get('phase') != phase:
                errors.append(f'{phase}: receipt identity mismatch')
            result = run_receipt_validator(receipt_path, run / 'manifest.yaml')
            if result.get('status') != 'approved':
                errors += result.get('errors', [f'{phase}: invalid receipt'])
            warnings += result.get('warnings', [])
            recorded = [e for e in ledger if e['event'] == 'phase_done' and e.get('phase') == phase]
            if len(recorded) != 1 or recorded[0].get('receipt_sha256') != digest(receipt_path):
                errors.append(f'{phase}: receipt is not bound to exactly one ledger event')
        ledger_result = run_tool('validate_ledger.py', run, run / 'manifest.yaml')
        if ledger_result.get('status') != 'ok':
            errors += ledger_result.get('issues', []) + [f'Missing phases: {ledger_result.get("missing_phases", [])}']
        git = git_state(manifest, run)
        if git['status'] == 'error':
            errors.append(git['error'])
        result = {'status': 'failed' if errors else 'complete', 'errors': errors, 'warnings': warnings,
                  'git': git, 'closeout': 'no-git' if git['status'] == 'no-git' else 'local',
                  'checked_at': now()}
        write_json(run / 'check_result.json', result, run)
        if not errors and not any(e['event'] == 'run_complete' for e in ledger):
            append_event(run, 'run_complete', status='complete')
        return save_report(run, result)

def cmd_status(run_value):
    run = owned_run(run_value)
    manifest = load_manifest(run) if (run / 'manifest.yaml').exists() else {}
    ledger = events(run)
    done = [e.get('phase') for e in ledger if e['event'] == 'phase_done']
    pending = [p['phase'] for p in manifest.get('phases', []) if p['decision'] == 'included' and p['phase'] not in done]
    result = {'status': 'saved', 'run_dir': str(run), 'report': str(run / 'report.md'), 'recorded': done,
              'pending': pending, 'next': pending[0] if pending else 'check',
              'note': 'Run check to validate current evidence; saved progress alone does not prove completion'}
    if any(e['event'] == 'stopped' for e in ledger):
        result.update(status='stopped', next='Revise the approach in a new run')
    elif not manifest:
        result.update(status='blocked', next='Read the saved report, resolve preflight and audit a revised task')
    else:
        errors = integrity_errors(run, manifest)
        if errors:
            result.update(status='blocked', errors=errors, next='Resolve the audit/integrity problem before continuing')
        elif pending:
            result['assignment'] = assignment(pending[0])
    return result

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    c = sub.add_parser('configure'); c.add_argument('--root', required=True)
    a = sub.add_parser('audit'); a.add_argument('task'); a.add_argument('--project'); a.add_argument('--force', action='store_true'); a.add_argument('--override-reason'); a.add_argument('--max-phases', type=int)
    r = sub.add_parser('record'); r.add_argument('run'); r.add_argument('--receipt', required=True)
    c = sub.add_parser('check'); c.add_argument('run'); c.add_argument('--dry-run', action='store_true', help='Compatibility option; checks never publish')
    s = sub.add_parser('status'); s.add_argument('run')
    args = parser.parse_args()
    try:
        if args.command == 'configure': result = configure(args.root)
        elif args.command == 'audit': result = cmd_audit(args.task, args.force, args.max_phases, args.project, args.override_reason)
        elif args.command == 'record': result = cmd_record(args.run, args.receipt)
        elif args.command == 'check': result = cmd_check(args.run, args.dry_run)
        else: result = cmd_status(args.run)
    except Exception as exc:
        result = {'status': 'blocked', 'errors': [str(exc)]}
        if getattr(args, 'run', None):
            try:
                run = owned_run(args.run)
                with locked(run):
                    result = save_report(run, result)
            except Exception:
                pass  # Preserve evidence when its destination or lock is unsafe.
    print(json.dumps(result, ensure_ascii=True, indent=2))
    return 1 if result['status'] in ('failed', 'blocked', 'stopped') else 2 if result['status'] == 'flagged' else 0

def make_run_id() -> str:
    now = datetime.now()
    return f"arc_{now.strftime('%Y%m%d_%H%M%S')}_{os.urandom(2).hex()}"

def load_yaml(path: Path) -> dict:
    import yaml
    return yaml.safe_load(path.read_text(encoding='utf-8'))

def parse_task_frontmatter(task_path: Path) -> dict:
    text = task_path.read_text(encoding='utf-8')
    if not text.startswith("---"):
        return {}
    end = text.find("---", 3)
    if end == -1:
        raise ValueError('Unclosed task frontmatter')
    import yaml
    try:
        result = yaml.safe_load(text[3:end]) or {}
        if not isinstance(result, dict):
            raise ValueError('Task frontmatter must be an object')
        return result
    except yaml.YAMLError as exc:
        raise ValueError('Invalid task YAML') from exc

def get_default_reasons() -> dict:
    catalog = load_phase_catalog()
    reasons = {}
    for p in catalog:
        if p.get("default_reason"):
            reasons[p["id"]] = p["default_reason"]
    return reasons

def build_manifest(task_ref: str, frontmatter: dict,
                   include_all: bool = True) -> dict:
    catalog = load_phase_catalog()
    mandatory_ids = {p["id"] for p in catalog if p.get("mandatory")}
    default_reasons = get_default_reasons()

    phases = []
    requested = frontmatter.get("phases", {})
    if not isinstance(requested, dict) or set(requested) - {p['id'] for p in catalog}:
        raise ValueError('Task phases must be an object of known phase names')
    for name, choice in requested.items():
        if not isinstance(choice, dict) or choice.get('decision') not in ('included', 'excluded'):
            raise ValueError(f'Invalid phase decision: {name}')
        if name in mandatory_ids and choice['decision'] == 'excluded':
            raise ValueError(f'Mandatory phase cannot be excluded: {name}')
    for p in catalog:
        pid = p["id"]
        if pid in mandatory_ids:
            phases.append({"phase": pid, "decision": "included"})
            continue
        requested_phase = requested.get(pid, {})
        if requested_phase.get("decision") == "excluded":
            phases.append({
                "phase": pid,
                "decision": "excluded",
                "reason_code": requested_phase.get("reason_code", default_reasons.get(pid)),
                "evidence_ref": requested_phase.get("evidence_ref", task_ref),
            })
        else:
            phases.append({"phase": pid, "decision": "included"})

    manifest = {
        "run_id": make_run_id(),
        "task_ref": task_ref,
        "phases": phases,
        "lessons_ack": frontmatter.get("lessons_ack", []),
        "governance_ack": frontmatter.get("governance_ack", []),
        "deliverables": frontmatter.get("deliverables", []),
    }

    if frontmatter.get("project_root"):
        manifest["project_root"] = str(Path(frontmatter["project_root"]).expanduser().resolve())
    for entry in phases:
        supplied = requested.get(entry["phase"], {})
        if supplied.get("deliverables"):
            entry["deliverables"] = supplied["deliverables"]
    return manifest

def main() -> int:
    if len(sys.argv) < 2:
        print("Usage: generate_manifest.py <task.md> [--output <path>]", file=sys.stderr)
        return 1

    task_path = Path(sys.argv[1]).expanduser().resolve()
    if not task_path.exists():
        print(f"ERROR: task.md not found: {task_path}", file=sys.stderr)
        return 1

    # Parse args
    output_path = None
    for i, arg in enumerate(sys.argv[2:], start=2):
        if arg == "--output" and i + 1 < len(sys.argv):
            output_path = Path(sys.argv[i + 1]).expanduser()
        elif arg == "--no-default-include":
            include_all = False

    # Default output: neben task.md
    if output_path is None:
        output_path = task_path.parent / "manifest.yaml"

    task_ref = str(task_path)
    frontmatter = parse_task_frontmatter(task_path)

    manifest = build_manifest(task_ref, frontmatter, include_all=True)

    write_manifest(manifest, output_path)

    # Kurzvalidierung
    from validate_manifest import audit_manifest
    audit = audit_manifest(str(output_path))
    status = audit["status"]
    print(f"  Auditor:   {status}")
    if status == "flagged":
        for f in audit.get("flags", []):
            print(f"    ⚑ {f.get('phase')}: {f.get('reason', '')[:80]}")
        return 2
    elif status == "blocked":
        for v in audit.get("violations", []):
            print(f"    🔴 {v.get('phase')}: {v.get('detail', '')[:80]}")
        return 2

    return 0

def rel_to_repo(path: Path, repo_root: Path) -> str:
    path = path.expanduser().resolve()
    try:
        return path.relative_to(repo_root).as_posix()
    except ValueError:
        return os.path.relpath(str(path), str(repo_root)).replace(os.sep, '/')

def _git_toplevel(path: Path) -> Optional[Path]:
    import subprocess
    try:
        r = subprocess.run(["git", "-C", str(path), "rev-parse", "--show-toplevel"],
                           capture_output=True, text=True, timeout=10)
    except Exception:
        return None
    if r.returncode != 0:
        return None
    return Path(r.stdout.strip()).resolve()

def _set_resolution_bases(task_path: Optional[Path], run_dir: Optional[Path]) -> None:
    global _RESOLUTION_BASES
    bases: list[Path] = []
    if task_path is not None:
        repo = _git_toplevel(task_path.parent if task_path.is_file() else task_path)
        if repo is not None:
            bases.append(repo)
    if task_path is not None:
        bases.append(task_path.parent if task_path.is_file() else task_path)
    bases.append(ARC_ROOT)
    if run_dir is not None:
        bases.append(run_dir)
    seen: set = set()
    _RESOLUTION_BASES = [b for b in bases if not (b in seen or seen.add(b))]

def _resolve_candidates(ref: str) -> list[Path]:
    if not ref:
        return []
    p = Path(ref).expanduser()
    if p.is_absolute():
        return [p] if p.exists() else []
    hits: list[Path] = []
    for base in _RESOLUTION_BASES:
        cand = base / p
        if cand.exists() and cand not in hits:
            hits.append(cand)
    return hits

def load_schema(name: str) -> dict:
    path = SCHEMA_DIR / f"{name}.schema.json"
    return json.loads(path.read_text(encoding='utf-8'))

def validate_schema(instance: dict) -> Optional[str]:
    error, _degraded = validate_schema_with_engine(instance)
    return error

def validate_schema_with_engine(instance: dict) -> Tuple[Optional[str], bool]:
    try:
        import jsonschema
        schema = load_schema("manifest")
        jsonschema.validate(instance, schema)
        return None, False
    except ImportError:
        # Fallback: minimale Schema-Prüfung ohne jsonschema
        return _minimal_schema_check(instance), True
    except jsonschema.ValidationError as e:
        return f"SCHEMA_INVALID: {e.message}", False

def _minimal_schema_check(instance: dict) -> Optional[str]:
    required = ["run_id", "task_ref", "phases"]
    for field in required:
        if field not in instance:
            return f"SCHEMA_INVALID: missing required field '{field}'"
    if not isinstance(instance["phases"], list) or len(instance["phases"]) < 3:
        return "SCHEMA_INVALID: phases must be a list with ≥3 entries"
    for p in instance["phases"]:
        if "phase" not in p or "decision" not in p:
            return f"SCHEMA_INVALID: phase entry missing 'phase' or 'decision': {p}"
        if p["decision"] not in ("included", "excluded"):
            return f"SCHEMA_INVALID: decision must be 'included' or 'excluded', got '{p['decision']}'"
        if p["decision"] == "excluded":
            if "reason_code" not in p:
                return f"SCHEMA_INVALID: excluded phase '{p['phase']}' missing reason_code"
            if p.get("reason_code") != "OPERATOR_ASSERTED" and "evidence_ref" not in p:
                return f"SCHEMA_INVALID: excluded phase '{p['phase']}' missing evidence_ref"
    return None

def load_catalog() -> dict:
    import yaml
    path = CONFIG_DIR / "phase_catalog.yaml"
    return yaml.safe_load(path.read_text(encoding='utf-8'))

def load_exclusion_rules() -> dict:
    import yaml
    path = CONFIG_DIR / "exclusion_rules.yaml"
    return yaml.safe_load(path.read_text(encoding='utf-8'))

def get_valid_codes_for_phase(rules: dict, phase: str) -> list[str]:
    valid = []
    for rule in rules["rules"]:
        if phase in rule["valid_for"]:
            valid.append(rule["reason_code"])
    return valid

def load_lessons() -> list[dict]:
    import yaml
    rows = []
    root = personal_root(required=False)
    paths = [LESSONS_PATH] + ([root / "lessons.yaml"] if root else [])
    for path in paths:
        if path.is_file():
            raw = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
            rows.extend(raw.get("lessons", []))
    ids = [row["id"] for row in rows]
    if len(ids) != len(set(ids)):
        raise ValueError("Duplicate lesson IDs across seed and personal registry")
    return rows

def _lesson_matches(trigger: dict, manifest: dict, phase_names: set) -> bool:
    # trigger.always → immer match
    if trigger.get("always"):
        return True

    # phase_included: Phase muss im Manifest sein
    if "phase_included" in trigger:
        if trigger["phase_included"] not in phase_names:
            return False

    # deliverable_glob: Prüft ob Manifest Deliverables das Muster treffen
    if "deliverable_glob" in trigger:
        import fnmatch
        dlvs = manifest.get("deliverables", [])
        pattern = trigger["deliverable_glob"]
        if not any(fnmatch.fnmatch(d, pattern) for d in dlvs):
            # Fallback: Phase-Deliverables prüfen
            phase_dlvs = []
            for p in manifest.get("phases", []):
                if p.get("deliverables"):
                    phase_dlvs.extend(p["deliverables"])
            if not any(fnmatch.fnmatch(d, pattern) for d in phase_dlvs):
                return False

    # keyword: Text in echtem task.md-Inhalt, nicht im Pfadstring.
    # Fallback auf task_ref-String nur wenn die Datei nicht auflösbar ist,
    # damit alte Fixtures ohne echtes task.md ihr bisheriges Verhalten behalten.
    if "keyword" in trigger:
        import re
        task_ref = manifest.get("task_ref", "")
        task_text = _read_ref_text_for_matching(task_ref)
        haystack = task_text if task_text is not None else task_ref
        if not re.search(trigger["keyword"], haystack, re.IGNORECASE):
            return False

    return True

def _read_ref_text_for_matching(ref: str) -> Optional[str]:
    for candidate in _resolve_candidates(ref):
        try:
            if candidate.is_file():
                text = candidate.read_text(encoding="utf-8")
                if text.startswith("---\n"):
                    text = text.split("---", 2)[-1]
                return text
        except OSError:
            continue
    return None

def _resolve_ref_path(ref: str) -> Optional[Path]:
    hits = _resolve_candidates(ref)
    return hits[0] if hits else None

def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def read_task_text(manifest: dict) -> Optional[str]:
    task_path = _resolve_ref_path(manifest.get("task_ref", ""))
    if task_path is None or not task_path.is_file():
        return None
    try:
        text = task_path.read_text(encoding="utf-8")
        return text.split("---", 2)[-1] if text.startswith("---\n") else text
    except OSError:
        return None

def load_governance_modules() -> dict:
    import yaml
    if not GOVERNANCE_PATH.exists():
        return {}
    raw = yaml.safe_load(GOVERNANCE_PATH.read_text(encoding='utf-8'))
    if not raw or "modules" not in raw:
        return {}
    return raw["modules"]

def _governance_trigger_matches(trigger: dict, text: str) -> bool:
    import re
    if "any" not in trigger and "all" not in trigger:
        return False
    ok = True
    if "any" in trigger:
        ok = ok and any(re.search(pat, text, re.IGNORECASE) for pat in trigger["any"])
    if "all" in trigger:
        ok = ok and all(re.search(pat, text, re.IGNORECASE) for pat in trigger["all"])
    return ok

def audit_manifest(manifest_path: str) -> dict:
    import yaml
    manifest_raw = yaml.safe_load(Path(manifest_path).read_text(encoding='utf-8'))
    catalog = load_catalog()
    rules = load_exclusion_rules()
    mandatory = get_mandatory_phases(catalog)
    phase_order = get_phase_order(catalog)

    result = {
        "run_id": manifest_raw.get("run_id", "unknown"),
        "manifest_ref": manifest_path,
        "schema_mode": "jsonschema",
        "status": "approved",
        "flags": [],
        "annotations": [],
        "violations": [],
        "timestamp": __import__("datetime").datetime.now().isoformat(),
    }

    result["manifest_sha256"] = _sha256_file(Path(manifest_path))

    # nach task_ref-Auflösung final inkl. Task-Repo.
    run_dir = Path(manifest_path).resolve().parent
    _set_resolution_bases(None, run_dir)

    # Integrity Core: task_ref ist die Quelle für Lessons/Governance-Trigger.
    # Wenn sie nicht auflösbar ist, darf die Prüfung nicht still übersprungen werden.
    task_path = _resolve_ref_path(manifest_raw.get("task_ref", ""))
    _set_resolution_bases(task_path, run_dir)
    if manifest_raw.get('project_root'):
        project = Path(manifest_raw['project_root']).expanduser().resolve()
        if not project.is_dir():
            result['violations'].append({'phase': '_project', 'rule': 'PROJECT_NOT_FOUND',
                                         'detail': 'Target workspace does not exist'})
        elif project not in _RESOLUTION_BASES:
            _RESOLUTION_BASES.insert(0, project)
    if task_path is None or not task_path.is_file():
        result["violations"].append({
            "phase": "_task",
            "rule": "TASK_REF_NOT_FOUND",
            "detail": f"task_ref cannot be resolved: {manifest_raw.get('task_ref', '')}",
        })

    # Prüfung 1: Schema validieren
    schema_error, schema_degraded = validate_schema_with_engine(manifest_raw)
    if schema_degraded:
        result["schema_mode"] = "minimal_degraded"
        result["flags"].append({
            "phase": "_schema",
            "rule": "SCHEMA_DEGRADED",
            "reason": "SCHEMA_DEGRADED: jsonschema unavailable; minimal fallback used",
            "severity": "warn",
        })
    if schema_error:
        result["status"] = "blocked"
        result["violations"].append({
            "phase": "_schema",
            "rule": "SCHEMA_INVALID",
            "detail": schema_error,
        })
        return result

    phases = manifest_raw["phases"]
    actual = [p["phase"] for p in phases]
    if actual != phase_order:
        result["violations"].append({"phase": "_catalog", "rule": "PHASE_CATALOG_MISMATCH",
                                     "detail": "Include every catalog phase exactly once, in order"})
    phase_names = {p["phase"] for p in phases if p["decision"] == "included"}

    # Schema-Validierung: lessons_ack-Einträge
    ack_list = manifest_raw.get("lessons_ack", [])
    lessons = load_lessons()
    valid_ids = {l["id"] for l in lessons}
    for ack in ack_list:
        if not isinstance(ack, dict):
            result["flags"].append({
                "phase": "_schema",
                "rule": "ACK_INVALID",
                "detail": f"lessons_ack entry is not an object: {ack}",
            })
            continue
        if ack.get("id") not in valid_ids:
            result["flags"].append({
                "phase": "_schema",
                "rule": "ACK_ID_UNKNOWN",
                "detail": f"lessons_ack.id '{ack.get('id')}' does not exist in the registry",
            })
        if ack.get("status") not in ("applied", "not_applicable"):
            result["flags"].append({
                "phase": "_schema",
                "rule": "ACK_STATUS_INVALID",
                "detail": f"lessons_ack.status '{ack.get('status')}' — expected 'applied' or 'not_applicable'",
            })

    # Prüfung 2: Mandatory-Phasen nicht excluded
    for m in mandatory:
        if m not in phase_names:
            result["status"] = "blocked"
            result["violations"].append({
                "phase": m,
                "rule": "MANDATORY_EXCLUDED",
                "detail": f"Mandatory phase '{m}' is missing from the manifest",
            })
        else:
            entry = next(p for p in phases if p["phase"] == m)
            if entry["decision"] != "included":
                result["status"] = "blocked"
                result["violations"].append({
                    "phase": m,
                    "rule": "MANDATORY_EXCLUDED",
                    "detail": f"Mandatory phase '{m}' was excluded (reason: {entry.get('reason_code', 'none')})",
                })

    # Prüfung 3+4+5: reason_codes, evidence, deliverables
    for p in phases:
        if p["decision"] != "excluded":
            continue
        code = p.get("reason_code", "")
        valid_codes = get_valid_codes_for_phase(rules, p["phase"])

        if code not in valid_codes:
            if code == "OPERATOR_ASSERTED":
                result["flags"].append({
                    "phase": p["phase"],
                    "reason": f"OPERATOR_ASSERTED — no checkable evidence",
                    "evidence": p.get("evidence_ref", "none"),
                })
            else:
                result["violations"].append({
                    "phase": p["phase"],
                    "rule": "INVALID_REASON_CODE",
                    "detail": f"'{code}' is not allowed for phase '{p['phase']}'. Allowed: {valid_codes}",
                })
        elif code == "OPERATOR_ASSERTED":
            # Auch wenn OPERATOR_ASSERTED in valid_for ist: immer flaggen.
            # Der Operator muss jeden Ausschluss bestätigen — stille Annahmen sind
            # gefährlicher als explizite Prüfung (Erkenntnis aus 2026-07-05: tested ≠ validated).
            result["flags"].append({
                "phase": p["phase"],
                "reason": "OPERATOR_ASSERTED — unresolved exclusion",
                "evidence": p.get("evidence_ref", "none"),
            })

        if code != "OPERATOR_ASSERTED":
            ev = p.get("evidence_ref", "")
            if not ev:
                result["violations"].append({
                    "phase": p["phase"],
                    "rule": "MISSING_EVIDENCE",
                    "detail": f"Phase '{p['phase']}' excluded without evidence_ref",
                })
            else:
                hits = _resolve_candidates(ev)
                if not hits:
                    result["flags"].append({
                        "phase": p["phase"],
                        "reason": f"EVIDENCE_NOT_FOUND: '{ev}' does not exist",
                        "evidence": ev,
                    })
                elif len(hits) > 1:
                    result["flags"].append({
                        "phase": p["phase"],
                        "rule": "EVIDENCE_AMBIGUOUS",
                        "reason": f"EVIDENCE_AMBIGUOUS: '{ev}' resolves at {len(hits)} locations: "
                                  + " | ".join(str(h) for h in hits),
                        "evidence": ev,
                    })

        # Prüfung 5: deliverables für NO_CODE-Prädikat
        if code == "NO_CODE":
            deliverables = manifest_raw.get("deliverables", []) + [d for phase in phases for d in phase.get("deliverables", [])]
            if deliverables:
                code_files = [d for d in deliverables if d.endswith((".py", ".ts", ".tsx", ".js", ".jsx", ".sh", ".ps1", ".go", ".java", ".rs", ".cs"))]
                if code_files:
                    result["flags"].append({
                        "phase": p["phase"],
                        "reason": f"NO_CODE with executable deliverables: {code_files}",
                        "evidence": str(deliverables),
                    })

    # Prüfung 6: Lessons-Registry
    lessons = load_lessons()
    if lessons:
        for lesson in lessons:
            if lesson.get("status") != "active":
                continue
            trigger = lesson.get("trigger", {})
            if not _lesson_matches(trigger, manifest_raw, phase_names):
                continue
            # Lesson matched → prüfe ob Manifest sie acknowledge
            ack_list = manifest_raw.get("lessons_ack", [])
            acked = next((a for a in ack_list if isinstance(a, dict) and a.get("id") == lesson["id"]), None)
            if not acked:
                entry = {
                    "phase": "_lessons",
                    "reason": f"LESSON_MATCH: {lesson['id']} — {lesson['rule'][:100]}",
                    "lessons_id": lesson["id"],
                    "rule": lesson["rule"],
                    "severity": "note",
                }
                # A match suggests relevant guidance; it does not create a new gate.
                result["annotations"].append(entry)
                continue
            if acked.get("status") not in ("applied", "not_applicable"):
                result["flags"].append({
                    "phase": "_lessons",
                    "reason": f"LESSON_ACK_INVALID: {lesson['id']} — status must be 'applied' or 'not_applicable'",
                    "lessons_id": lesson["id"],
                    "ack_status": acked.get("status"),
                })
                continue
            if acked.get("status") == "not_applicable":
                reason = acked.get("reason")
                if not isinstance(reason, str) or not reason.strip():
                    result["flags"].append({
                        "phase": "_lessons", "rule": "LESSON_ACK_NO_REASON",
                        "lessons_id": lesson["id"],
                        "reason": "Explain why this lesson does not apply in the existing task",
                    })
                else:
                    result["annotations"].append({
                        "phase": "_lessons", "lessons_id": lesson["id"],
                        "reason": "LESSON_NOT_APPLICABLE", "ack_reason": reason,
                        "severity": "note",
                    })
            # Guidance acknowledgments do not require separate proof artifacts.
            # Actual work is evidenced by the selected phase receipts.

    # Prüfung 7: Governance-Module (Lifecycle Adoption Proof)
    gov_modules = load_governance_modules()
    task_text = read_task_text(manifest_raw)
    if gov_modules and task_text is not None:
        gov_ack = manifest_raw.get("governance_ack", [])
        acks_by_module = {a.get("module"): a for a in gov_ack if isinstance(a, dict)}
        for mod_name, mod in gov_modules.items():
            if not _governance_trigger_matches(mod.get("trigger", {}), task_text):
                continue
            ack = acks_by_module.get(mod_name)
            if ack is None:
                result["annotations"].append({
                    "phase": "_governance", "module": mod_name,
                    "reason": f"GOVERNANCE_SUGGESTION: assess '{mod_name}' against the current task; keyword matches do not require extra work",
                    "severity": "note",
                })
                continue
            # Ack vorhanden → Status + Planzeit-Felder prüfen
            status = ack.get("status")
            if status not in ("included", "not_applicable", "anchor_missing"):
                result["flags"].append({
                    "phase": "_governance",
                    "module": mod_name,
                    "reason": f"GOVERNANCE_ACK_STATUS_INVALID: '{status}' for module '{mod_name}'",
                })
                continue
            if status == "not_applicable" and not ack.get("reason"):
                result["flags"].append({
                    "phase": "_governance",
                    "module": mod_name,
                    "reason": f"GOVERNANCE_ACK_NO_REASON: '{mod_name}' marked not_applicable without a reason",
                })
            if mod_name == "pipeline_chunking" and status == "included":
                for field in ("input_validator_ref", "validator_command", "validator_output_ref"):
                    if not ack.get(field):
                        result["flags"].append({
                            "phase": "_governance",
                            "module": mod_name,
                            "reason": f"GOVERNANCE_PLAN_FIELD_MISSING: pipeline_chunking.included without '{field}' (observed verdict belongs in the receipt)",
                        })

    # Finaler Status: blocked > flagged > approved
    if len(result["violations"]) > 0:
        result["status"] = "blocked"
    elif len(result["flags"]) > 0:
        result["status"] = "flagged"
    else:
        result["status"] = "approved"

    return result

def main():
    if len(sys.argv) < 2:
        print("Usage: validate_manifest.py <manifest.yaml>", file=sys.stderr)
        sys.exit(1)

    manifest_path = sys.argv[1]
    if not os.path.exists(manifest_path):
        print(f"Manifest not found: {manifest_path}", file=sys.stderr)
        sys.exit(1)

    result = audit_manifest(manifest_path)
    print(json.dumps(result, indent=2, ensure_ascii=False))

    if result["status"] == "blocked":
        sys.exit(1)
    elif result["status"] == "flagged":
        sys.exit(2)
    else:
        sys.exit(0)

def validate_schema(instance: Dict[str, Any]) -> List[str]:
    try:
        import jsonschema  # type: ignore
        schema = load_json(SCHEMA_PATH)
        jsonschema.validate(instance, schema)
        return []
    except ImportError:
        return minimal_schema_check(instance)
    except Exception as exc:
        return [f"SCHEMA_INVALID: {exc}"]

def minimal_schema_check(instance: Dict[str, Any]) -> List[str]:
    errors: List[str] = []
    required = ["run_id", "phase", "gate", "ok", "timestamp"]
    for field in required:
        if field not in instance:
            errors.append(f"MISSING_FIELD: {field}")
    if errors:
        return errors
    if not isinstance(instance["run_id"], str):
        errors.append("FIELD_TYPE: run_id must be string")
    if not isinstance(instance["phase"], str):
        errors.append("FIELD_TYPE: phase must be string")
    if not isinstance(instance["gate"], str):
        errors.append("FIELD_TYPE: gate must be string")
    if not isinstance(instance["ok"], bool):
        errors.append("FIELD_TYPE: ok must be boolean")
    if "evidence" in instance and instance["evidence"] is not None and not isinstance(instance["evidence"], (str, dict)):
        errors.append("FIELD_TYPE: evidence must be string|object|null")
    if not isinstance(instance["timestamp"], str):
        errors.append("FIELD_TYPE: timestamp must be string")
    return errors

def resolve_path(ref: str, receipt_path: Path) -> Optional[Path]:
    raw = Path(ref).expanduser()
    candidates: List[Path] = []
    if raw.is_absolute():
        candidates.append(raw)
    else:
        candidates.extend([
            (receipt_path.parent / raw),
            (receipt_path.parent.parent / raw),
            (ARC_ROOT / raw),
            (Path.cwd() / raw),
        ])
    for candidate in candidates:
        resolved = candidate.resolve()
        if resolved.exists():
            return resolved
    return None

def require_file(ref: Any, receipt_path: Path, label: str, errors: List[str]) -> Optional[Path]:
    if not isinstance(ref, str) or not ref.strip():
        errors.append(f"{label}: missing path")
        return None
    resolved = resolve_path(ref, receipt_path)
    if resolved is None or not resolved.is_file():
        errors.append(f"{label}: path not found: {ref}")
        return None
    return resolved

def require_dict(value: Any, label: str, errors: List[str]) -> Optional[Dict[str, Any]]:
    if not isinstance(value, dict):
        errors.append(f"{label}: expected object")
        return None
    return value

def require_nonempty_str(value: Any, label: str, errors: List[str]) -> Optional[str]:
    if not isinstance(value, str) or not value.strip():
        errors.append(f"{label}: expected non-empty string")
        return None
    return value.strip()

def _default_board_db(board: str) -> Path:
    if board == "default":
        return personal_root() / "kanban.db"
    return personal_root() / "kanban" / "boards" / board / "kanban.db"

def validate_kanban_payload(payload: Any, receipt_path: Path, errors: List[str], expected_status: Optional[str] = None) -> None:
    data = require_dict(payload, "kanban", errors)
    if data is None:
        return
    board = data.get("board")
    board_db = data.get("board_db")
    if not isinstance(board_db, str) or not board_db.strip():
        board = require_nonempty_str(board, "kanban.board", errors)
        if board is not None:
            board_db_path = _default_board_db(board)
        else:
            board_db_path = None
    else:
        board_db_path = Path(board_db).expanduser().resolve()
    if board_db_path is None:
        return
    if not board_db_path.exists():
        errors.append(f"kanban.board_db: path not found: {board_db_path}")
        return
    task_ids = data.get("task_ids")
    if not isinstance(task_ids, list) or not task_ids or not all(isinstance(t, str) and t.strip() for t in task_ids):
        errors.append("kanban.task_ids: expected non-empty string list")
        return
    conn = None
    try:
        conn = sqlite3.connect(str(board_db_path), timeout=5.0)
        placeholders = ",".join("?" for _ in task_ids)
        rows = conn.execute(
            f"SELECT id, status FROM tasks WHERE id IN ({placeholders})",
            task_ids,
        ).fetchall()
    except Exception as exc:
        errors.append(f"kanban.query_failed: {exc}")
        return
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass
    row_map = {row[0]: row[1] for row in rows}
    missing = [task_id for task_id in task_ids if task_id not in row_map]
    if missing:
        errors.append(f"kanban.missing_tasks: {', '.join(missing)}")
    for task_id, status in row_map.items():
        if status not in VALID_STATUSES:
            errors.append(f"kanban.invalid_status[{task_id}]: {status}")
        if expected_status is not None and status != expected_status:
            errors.append(f"kanban.unexpected_status[{task_id}]: expected {expected_status}, got {status}")

def validate_understand(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    preflight = require_dict(evidence.get("preflight"), "understand.preflight", errors)
    if preflight is None:
        return
    status = require_nonempty_str(preflight.get("status"), "understand.preflight.status", errors)
    if status not in {"clean", "override"}:
        errors.append("understand.preflight.status: expected clean|override")
    require_file(preflight.get("evidence_ref"), receipt_path, "understand.preflight.evidence_ref", errors)
    require_file(evidence.get("problem_ref"), receipt_path, "understand.problem_ref", errors)
    require_nonempty_str(evidence.get("code_ref"), "understand.code_ref", errors)

def validate_spike(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    verdict = require_nonempty_str(evidence.get("verdict"), "spike.verdict", errors)
    if verdict not in {"VALIDATED", "PARTIAL", "INVALIDATED"}:
        errors.append("spike.verdict: expected VALIDATED|PARTIAL|INVALIDATED")
    require_file(evidence.get("evidence_ref"), receipt_path, "spike.evidence_ref", errors)

def validate_plan(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_file(evidence.get("plan_ref"), receipt_path, "plan.plan_ref", errors)
    # wenn vorhanden, muss er echt sein.
    if evidence.get("kanban") is not None:
        validate_kanban_payload(evidence.get("kanban"), receipt_path, errors)

def validate_constraints(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_file(evidence.get("validator_ref"), receipt_path, "constraints.validator_ref", errors)
    if evidence.get("good_case_exit_code") != 0:
        errors.append("constraints.good_case_exit_code: expected 0")
    if evidence.get("bad_case_exit_code") != 1:
        errors.append("constraints.bad_case_exit_code: expected 1")

def validate_tdd(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_file(evidence.get("red_ref"), receipt_path, "tdd.red_ref", errors)
    require_file(evidence.get("green_ref"), receipt_path, "tdd.green_ref", errors)
    if evidence.get("suite_exit_code") != 0:
        errors.append("tdd.suite_exit_code: expected 0")

def validate_integration(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_file(evidence.get("activation_ref"), receipt_path, "integration.activation_ref", errors)
    require_file(evidence.get("fallback_ref"), receipt_path, "integration.fallback_ref", errors)

def validate_cron(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_nonempty_str(evidence.get("cron_schedule"), "cron.cron_schedule", errors)
    require_file(evidence.get("artefact_path"), receipt_path, "cron.artefact_path", errors)
    if evidence.get("artefact_valid") is not True:
        errors.append("cron.artefact_valid: expected true")

def validate_doc(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    docs = evidence.get("updated_docs")
    if not isinstance(docs, list) or not docs:
        errors.append("doc.updated_docs: expected non-empty list")
        return
    for idx, ref in enumerate(docs):
        require_file(ref, receipt_path, f"doc.updated_docs[{idx}]", errors)

def validate_verify(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    checks = evidence.get("checks")
    if not isinstance(checks, list) or not checks:
        errors.append("verify.checks: expected non-empty list")
        return
    live_seen = False
    for idx, check in enumerate(checks):
        item = require_dict(check, f"verify.checks[{idx}]", errors)
        if item is None:
            continue
        status = require_nonempty_str(item.get("status"), f"verify.checks[{idx}].status", errors)
        kind = require_nonempty_str(item.get("kind"), f"verify.checks[{idx}].kind", errors)
        if status != "pass":
            errors.append(f"verify.checks[{idx}].status: expected pass")
        if kind == "live":
            live_seen = True
        require_file(item.get("evidence_ref"), receipt_path, f"verify.checks[{idx}].evidence_ref", errors)
    if not live_seen:
        errors.append("verify.checks: at least one live check required")

def validate_postmortem(evidence: Dict[str, Any], receipt_path: Path, errors: List[str]) -> None:
    require_file(evidence.get("postmortem_ref"), receipt_path, "postmortem.postmortem_ref", errors)
    # aber die Extraktion muss nachweislich stattgefunden haben.
    lessons = require_dict(evidence.get("lessons"), "postmortem.lessons", errors)
    if lessons is not None:
        if not isinstance(lessons.get("extracted"), list):
            errors.append("postmortem.lessons.extracted: expected list (may be empty)")
        if "guard_impulse" in lessons and not isinstance(lessons.get("guard_impulse"), list):
            errors.append("postmortem.lessons.guard_impulse: expected list")
    if evidence.get("kanban") is not None:
        validate_kanban_payload(evidence.get("kanban"), receipt_path, errors, expected_status="done")
    cleanup = require_dict(evidence.get("cleanup"), "postmortem.cleanup", errors)
    if cleanup is None:
        return
    proof_artifacts = cleanup.get("proof_artifacts")
    if not isinstance(proof_artifacts, list) or not proof_artifacts:
        errors.append("postmortem.cleanup.proof_artifacts: expected non-empty list")
    else:
        for idx, ref in enumerate(proof_artifacts):
            require_file(ref, receipt_path, f"postmortem.cleanup.proof_artifacts[{idx}]", errors)
    process_removed = cleanup.get("process_artifacts_removed")
    if not isinstance(process_removed, list):
        errors.append("postmortem.cleanup.process_artifacts_removed: expected list")
    if process_removed:
        for idx, ref in enumerate(process_removed):
            if not isinstance(ref, str):
                errors.append(f"postmortem.cleanup.process_artifacts_removed[{idx}]: expected string")
    if cleanup.get("gitready") is not True:
        errors.append("postmortem.cleanup.gitready: expected true")

def _file_contains(path: Path, needle: str) -> bool:
    try:
        return needle.lower() in path.read_text(encoding='utf-8').lower()
    except OSError:
        return False

def validate_governance_consumer_map(gov: Dict[str, Any], receipt_path: Path,
                                     errors: List[str]) -> None:
    cm = gov.get("consumer_map")
    if not isinstance(cm, dict):
        return
    ref = require_file(cm.get("consumer_map_ref"), receipt_path,
                       "governance.consumer_map.consumer_map_ref", errors)
    if ref is None:
        return
    if not _file_contains(ref, "## Grep Evidence"):
        errors.append("governance.consumer_map: consumer map lacks '## Grep Evidence' section")
    if not _file_contains(ref, "Hardcoding"):
        errors.append("governance.consumer_map: consumer map lacks 'Hardcoding' column")

def validate_governance_pipeline_chunking(gov: Dict[str, Any], receipt_path: Path,
                                          errors: List[str]) -> None:
    pc = gov.get("pipeline_chunking")
    if not isinstance(pc, dict):
        return
    require_file(pc.get("input_validator_ref"), receipt_path,
                 "governance.pipeline_chunking.input_validator_ref", errors)
    out_ref = require_file(pc.get("validator_output_ref"), receipt_path,
                           "governance.pipeline_chunking.validator_output_ref", errors)
    llm_started = require_nonempty_str(pc.get("llm_run_started_at"),
                                       "governance.pipeline_chunking.llm_run_started_at", errors)
    if out_ref is None:
        return
    try:
        out_data = json.loads(out_ref.read_text(encoding='utf-8'))
    except Exception as exc:
        errors.append(f"governance.pipeline_chunking.validator_output_ref: unreadable JSON: {exc}")
        return
    if out_data.get("verdict") != "pass":
        errors.append("governance.pipeline_chunking: validator verdict must be 'pass', "
                      f"got '{out_data.get('verdict')}'")
    out_ts = out_data.get("timestamp")
    if not isinstance(out_ts, str) or not out_ts.strip():
        errors.append("governance.pipeline_chunking: validator output missing 'timestamp'")
    elif llm_started:
        from datetime import datetime
        try:
            validator_time = datetime.fromisoformat(out_ts.replace('Z', '+00:00'))
            llm_time = datetime.fromisoformat(llm_started.replace('Z', '+00:00'))
            if validator_time.tzinfo is None or llm_time.tzinfo is None:
                raise ValueError('timezone required')
            if validator_time >= llm_time:
                errors.append('governance.pipeline_chunking: validator must run BEFORE llm')
        except ValueError:
            errors.append('governance.pipeline_chunking: valid timezone-aware timestamps required')

def validate_manifest_bound_governance(evidence: Dict[str, Any], receipt_path: Path,
                                       errors: List[str]) -> None:
    manifest_ref = evidence.get("manifest_ref")
    if not manifest_ref:
        return
    manifest_path = require_file(manifest_ref, receipt_path, "verify.manifest_ref", errors)
    if manifest_path is None:
        return
    try:
        import yaml  # type: ignore
        manifest = yaml.safe_load(manifest_path.read_text(encoding='utf-8'))
    except Exception as exc:
        errors.append(f"verify.manifest_ref: unreadable manifest: {exc}")
        return
    gov_ack = manifest.get("governance_ack", []) if isinstance(manifest, dict) else []
    required = [
        str(ack.get("module")) for ack in gov_ack
        if isinstance(ack, dict)
        and ack.get("module")
        and ack.get("status") in {"included", "anchor_missing"}
    ]
    if not required:
        return
    gov = evidence.get("governance")
    if not isinstance(gov, dict):
        errors.append(
            "verify.governance.consumer_map: missing governance evidence for manifest_ack: "
            + ", ".join(required))
        return
    for module in required:
        if not isinstance(gov.get(module), dict) or not gov[module]:
            errors.append(f"verify.governance.{module}: missing evidence for manifest governance_ack")

def validate_phase(receipt: Dict[str, Any], receipt_path: Path,
                   warnings: List[str]) -> List[str]:
    errors: List[str] = []
    if receipt.get("ok") is not True:
        errors.append("receipt.ok: expected true for completed phase")
        return errors
    evidence = require_dict(receipt.get("evidence"), "receipt.evidence", errors)
    if evidence is None:
        return errors
    phase = receipt.get("phase")
    if not isinstance(phase, str):
        errors.append("receipt.phase: expected string")
        return errors
    validators = {
        "understand": validate_understand,
        "spike": validate_spike,
        "plan": validate_plan,
        "constraints": validate_constraints,
        "tdd": validate_tdd,
        "integration": validate_integration,
        "cron": validate_cron,
        "doc": validate_doc,
        "verify": validate_verify,
        "postmortem": validate_postmortem,
    }
    fn = validators.get(phase)
    if fn is None:
        errors.append(f"unknown phase: {phase}")
        return errors
    fn(evidence, receipt_path, errors)
    if phase == "verify":
        validate_manifest_bound_governance(evidence, receipt_path, errors)
    # Governance-Evidence nur für verify-Receipts (Lifecycle Adoption Proof).
    if phase == "verify" and "governance" in evidence:
        validate_governance(evidence["governance"], receipt_path, errors, warnings)
    return errors

def main() -> int:
    if len(sys.argv) < 2:
        print("Usage: validate_receipt.py <receipt.json>", file=sys.stderr)
        return 1
    receipt_path = Path(sys.argv[1]).expanduser().resolve()
    receipt = load_json(receipt_path)
    manifest_arg: Optional[str] = None
    if "--manifest" in sys.argv:
        idx = sys.argv.index("--manifest")
        if idx + 1 < len(sys.argv):
            manifest_arg = sys.argv[idx + 1]
    if manifest_arg and receipt.get("phase") == "verify":
        evidence = receipt.setdefault("evidence", {})
        if isinstance(evidence, dict):
            evidence["manifest_ref"] = manifest_arg
    warnings: List[str] = []
    errors = validate_schema(receipt)
    if manifest_arg:
        import yaml
        bound = yaml.safe_load(Path(manifest_arg).read_text(encoding='utf-8'))
        if receipt.get("run_id") != bound.get("run_id"):
            errors.append("receipt.run_id: does not match manifest")
        if receipt.get("phase") not in {p["phase"] for p in bound["phases"] if p["decision"] == "included"}:
            errors.append("receipt.phase: not included in manifest")
    if not errors:
        errors = validate_phase(receipt, receipt_path, warnings)
    result = {
        "receipt": str(receipt_path),
        "phase": receipt.get("phase"),
        "status": "approved" if not errors else "blocked",
        "errors": errors,
        "warnings": warnings,
    }
    print(json.dumps(result, indent=2, ensure_ascii=False))
    return 0 if not errors else 1

def _read_events(ledger_path: Path) -> List[Dict[str, Any]]:
    events: List[Dict[str, Any]] = []
    if not ledger_path.exists():
        return events
    with open(ledger_path, encoding='utf-8') as f:
        for line_no, line in enumerate(f, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                events.append(json.loads(line))
            except json.JSONDecodeError as exc:
                events.append({"event": "_invalid_json", "line": line_no, "error": str(exc)})
    return events

def validate(run_dir: str, manifest: dict) -> dict:
    run_path = Path(run_dir)
    ledger_path = run_path / "ledger.jsonl"
    expected_run_id = manifest.get("run_id", "unknown")
    events = _read_events(ledger_path)

    missing = [p["phase"] for p in manifest["phases"] if p["decision"] == "included"]
    issues: List[str] = []

    if not ledger_path.exists():
        return {
            "run_id": expected_run_id,
            "status": "incomplete",
            "missing_phases": missing,
            "issues": ["ledger missing"],
        }

    done_phases = set()
    audit_events = []
    observed_order = []
    previous_ts = None
    for event in events:
        if event.get("event") == "_invalid_json":
            issues.append(f"ledger invalid json at line {event.get('line')}: {event.get('error')}")
            continue
        if event.get("event") in {"manifest_proposed", "audit", "phase_done", "PENDING_JUDGMENT", "operator_approved", "run_complete"}:
            if event.get("run_id") != expected_run_id:
                issues.append(
                    f"run_id mismatch in {event.get('event')}: expected {expected_run_id}, got {event.get('run_id')}"
                )
        if event.get("event") == "audit":
            audit_events.append(event)
        if event.get("event") == "phase_done" and event.get("ok"):
            done_phases.add(event.get("phase"))
            observed_order.append(event.get("phase"))
        try:
            from datetime import datetime
            stamp = datetime.fromisoformat(event["ts"].replace("Z", "+00:00"))
            if stamp.tzinfo is None or (previous_ts is not None and stamp < previous_ts):
                issues.append("ledger timestamp order or timezone invalid")
            previous_ts = stamp
        except (KeyError, ValueError, TypeError):
            issues.append("ledger timestamp invalid")

    expected_order = [p["phase"] for p in manifest["phases"] if p["decision"] == "included"]
    if observed_order != expected_order:
        issues.append("phase_done events must match included phases exactly once in order")
    if not audit_events or audit_events[0].get("status") != "approved":
        issues.append("approved audit event required before execution")
    if events and events[0].get("event") not in {"audit", "manifest_proposed"}:
        issues.append("ledger must start with its audit or manifest event")

    missing = []
    for p in manifest["phases"]:
        if p["decision"] == "included" and p["phase"] not in done_phases:
            missing.append(p["phase"])

    audit_result_path = run_path / "audit_result.json"
    if audit_result_path.exists():
        try:
            audit_result = json.loads(audit_result_path.read_text(encoding='utf-8'))
        except Exception as exc:
            issues.append(f"audit_result unreadable: {exc}")
        else:
            if audit_result.get("run_id") != expected_run_id:
                issues.append(
                    f"audit_result run_id mismatch: expected {expected_run_id}, got {audit_result.get('run_id')}"
                )
            if audit_events:
                last_audit = audit_events[-1]
                if last_audit.get("status") != audit_result.get("status"):
                    issues.append(
                        f"audit status mismatch: ledger={last_audit.get('status')} audit_result={audit_result.get('status')}"
                    )
                if last_audit.get("status") == "approved" and audit_result.get("status") != "approved":
                    issues.append("ledger audit approved contradicts non-approved audit_result")
    elif audit_events:
        issues.append("ledger has audit event but audit_result.json is missing")

    status = "ok" if not missing and not issues else "incomplete"
    return {
        "run_id": expected_run_id,
        "status": status,
        "missing_phases": missing,
        "issues": issues,
        "errors": issues,
    }

def private_path(value, owner=None):
    path = Path(value).expanduser().resolve()
    if path == SKILL_ROOT or SKILL_ROOT in path.parents or path in SKILL_ROOT.parents:
        raise ValueError("Personal state must be outside the distributed skill")
    if any((parent / ".git").exists() for parent in (path, *path.parents)):
        raise ValueError("Personal state must be outside Git repositories")
    if owner is not None:
        owner = Path(owner).expanduser().resolve()
        if path != owner and owner not in path.parents:
            raise ValueError("Personal destination redirects outside its owning folder")
    return path

def config_path():
    base = os.environ.get("XDG_CONFIG_HOME") or str(Path.home() / ".config")
    return private_path(Path(base) / "delivery-workflow" / "config.json")

def personal_root(required=True):
    value = os.environ.get("DELIVERY_WORKFLOW_HOME") or os.environ.get("DELIVERY_WORKFLOW_ROOT")
    if not value and config_path().is_file():
        value = json.loads(config_path().read_text(encoding="utf-8")).get("root")
    if value:
        return private_path(value)
    if required:
        raise ValueError("Choose a personal folder first: arc_run.py configure --root <folder>")
    return None

def configure(root):
    root = private_path(root)
    root.mkdir(parents=True, exist_ok=True)
    private_path(root / "arc_runs", root).mkdir(exist_ok=True)
    registry = private_path(root / "lessons.yaml", root)
    if not registry.exists():
        write(registry, "versions:\n  lessons: 1\nlessons: []\n", root)
    write_json(config_path(), {"root": str(root)})
    return {"status": "ok", "root": str(root), "config": str(config_path())}

def locked(folder):
    folder = private_path(folder)
    folder.mkdir(parents=True, exist_ok=True)
    lock = private_path(folder / ".delivery-workflow.lock", folder)
    try:
        fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except FileExistsError:
        raise ValueError("Another write is active; inspect a stale lock before removing it")
    try:
        os.close(fd)
        yield
    finally:
        lock.unlink(missing_ok=True)

def load_registry():
    path = private_path(personal_root() / 'lessons.yaml', personal_root())
    return yaml.safe_load(path.read_text(encoding='utf-8')) if path.is_file() else {'versions': {'lessons': 1}, 'lessons': []}

def learn(run_value, entry_value, reply):
    from arc_run import owned_run
    run = owned_run(run_value)
    if not reply.strip():
        raise ValueError('The actual user confirmation is required')
    result = json.loads((run / 'check_result.json').read_text(encoding='utf-8'))
    if result.get('status') != 'complete':
        raise ValueError('Deliver and verify the run before saving a method improvement')
    entry = json.loads(Path(entry_value).read_text(encoding='utf-8'))
    allowed = {'id', 'purpose', 'rule', 'context', 'limits', 'trigger'}
    if set(entry) - allowed or entry.get('purpose') != 'skill_improvement':
        raise ValueError('Only a skill_improvement entry is accepted; case-result fields are not allowed')
    for field in ('id', 'rule', 'context', 'limits'):
        if not isinstance(entry.get(field), str) or not entry[field].strip():
            raise ValueError(f'{field} is required')
    if not re.fullmatch(r'P-[a-z0-9-]{3,60}', entry['id']):
        raise ValueError('Personal lesson IDs use P- followed by a short lowercase identifier')
    trigger = entry.get('trigger')
    if not isinstance(trigger, dict) or not trigger or set(trigger) - {'keyword', 'phase_included', 'deliverable_glob'}:
        raise ValueError('Use a narrow keyword, phase_included or deliverable_glob trigger')
    if not all(isinstance(v, str) and v.strip() for v in trigger.values()):
        raise ValueError('Trigger values must be nonempty strings')
    if 'keyword' in trigger:
        re.compile(trigger['keyword'])
    root = personal_root()
    with locked(root):
        registry = load_registry()
        prior = next((row for row in registry['lessons'] if row['id'] == entry['id']), None)
        if prior:
            if any(prior.get(k) != entry[k] for k in allowed):
                raise ValueError('This lesson ID already has different content; use a new ID')
            if run.name in prior['source_runs']:
                return {'status': 'ok', 'action': 'unchanged', 'id': prior['id']}
            prior['source_runs'].append(run.name)
            prior['occurrences'] += 1
        else:
            prior = {**entry, 'status': 'active', 'severity': 'note', 'source_runs': [run.name], 'occurrences': 1}
            registry['lessons'].append(prior)
        prior['updated'] = date.today().isoformat()
        # Confirmation stays with the case, outside the knowledge registry.
        write_json(run / 'learning' / f"{entry['id']}.json", {'entry': entry, 'user_reply': reply}, run)
        write(root / 'lessons.yaml', yaml.safe_dump(registry, sort_keys=False), root)
        return {'status': 'ok', 'id': entry['id'], 'registry': str(root / 'lessons.yaml')}

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    p = sub.add_parser('learn'); p.add_argument('--run', required=True); p.add_argument('--entry', required=True); p.add_argument('--reply', required=True)
    sub.add_parser('list'); sub.add_parser('guard-due')
    for action in ('retire', 'remove'):
        p = sub.add_parser(action); p.add_argument('id')
        p.add_argument('--reason', help='Why the rule is obsolete, replaced or no longer applicable')
        p.add_argument('--reply', help='Compatibility alias for an already supplied reason')
    args = parser.parse_args()
    try:
        if args.command == 'learn':
            result = learn(args.run, args.entry, args.reply)
        elif args.command in ('retire', 'remove'):
            reason = args.reason or args.reply
            if not reason or not reason.strip():
                raise ValueError('A reason for retiring or removing the rule is required')
            root = personal_root()
            with locked(root):
                registry = load_registry()
                item = next((row for row in registry['lessons'] if row['id'] == args.id), None)
                if item is None:
                    raise ValueError('No personal lesson with that ID')
                if args.command == 'remove':
                    registry['lessons'].remove(item)
                else:
                    item['status'] = 'retired'
                write(root / 'lessons.yaml', yaml.safe_dump(registry, sort_keys=False), root)
                result = {'status': 'ok', 'id': args.id, 'action': args.command, 'reason': reason}
        else:
            rows = load_registry()['lessons']
            if args.command == 'guard-due': rows = [r for r in rows if r.get('occurrences', 0) >= 2 and r.get('status') == 'active']
            result = {'status': 'ok', 'lessons': rows}
    except Exception as exc:
        result = {'status': 'blocked', 'error': str(exc)}
    print(json.dumps(result, indent=2))
    return 1 if result['status'] == 'blocked' else 0

def cmd_get(db_path: Path, task_id: str) -> int:
    conn = connect(db_path)
    try:
        row = conn.execute(
            "SELECT id, title, status, created_at FROM tasks WHERE id = ?", (task_id,)
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        print(json.dumps({"ok": False, "error": f"task not found: {task_id}"}))
        return 1
    print(json.dumps({"ok": True, "id": row[0], "title": row[1], "status": row[2], "created_at": row[3]}))
    return 0

def cmd_list(db_path: Path) -> int:
    conn = connect(db_path)
    try:
        rows = conn.execute(
            "SELECT id, title, status, created_at FROM tasks ORDER BY created_at"
        ).fetchall()
    finally:
        conn.close()
    print(json.dumps({"ok": True, "tasks": [
        {"id": r[0], "title": r[1], "status": r[2], "created_at": r[3]} for r in rows
    ]}))
    return 0

def main() -> int:
    args = sys.argv[1:]
    db_path = DEFAULT_DB
    if "--db" in args:
        idx = args.index("--db")
        if idx + 1 >= len(args):
            print("--db requires a path", file=sys.stderr)
            return 1
        db_path = Path(args[idx + 1]).expanduser().resolve()
        del args[idx:idx + 2]

    if db_path is None:
        db_path = personal_root() / "kanban.db"

    if not args:
        print(__doc__, file=sys.stderr)
        return 1

    cmd, rest = args[0], args[1:]
    if cmd == "init-db":
        return cmd_init_db(db_path)
    if cmd == "add" and len(rest) >= 2:
        return cmd_add(db_path, rest[0], rest[1], rest[2] if len(rest) > 2 else "todo")
    if cmd == "set-status" and len(rest) == 2:
        return cmd_set_status(db_path, rest[0], rest[1])
    if cmd == "get" and len(rest) == 1:
        return cmd_get(db_path, rest[0])
    if cmd == "list":
        return cmd_list(db_path)
    print(__doc__, file=sys.stderr)
    return 1

